  ('P5_14B', 'V', 1530, '14b', 'If Yes, has it filed a Form 720 to report these payments?', 'YESNO', 'carried', '', ''),
  ('P5_15', 'V', 1540, '15', 'Is the organization subject to the section 4960 tax on payments of more than $1,000,000 in remuneration or excess parachute payments?', 'YESNO', 'record', 'fn:section_4960', ''),
  ('P5_16', 'V', 1550, '16', 'Is the organization an educational institution subject to the section 4968 excise tax on net investment income?', 'YESNO', 'carried', '', ''),
  ('P5_17', 'V', 1560, '17', 'Section 501(c)(21) organizations. Did the trust or any disqualified person engage in activities resulting in an excise tax under section 4951, 4952 or 4953?', 'YESNO', 'carried', '', ''),
  ('P6_1A', 'VI', 1570, '1a', 'Enter the number of voting members of the governing body at the end of the tax year', 'COUNT', 'record', 'fn:voting_members', ''),
  ('P6_1B', 'VI', 1580, '1b', 'Enter the number of voting members included in line 1a who are independent', 'COUNT', 'record', 'fn:independent_members', ''),
  ('P6_2', 'VI', 1590, '2', 'Did any officer, director, trustee or key employee have a family relationship or a business relationship with any other officer, director, trustee or key employee?', 'YESNO', 'carried', '', ''),
  ('P6_3', 'VI', 1600, '3', 'Did the organization delegate control over management duties to a management company or other person?', 'YESNO', 'carried', '', ''),
  ('P6_4', 'VI', 1610, '4', 'Did the organization make any significant changes to its governing documents since the prior Form 990 was filed?', 'YESNO', 'carried', '', ''),
  ('P6_5', 'VI', 1620, '5', 'Did the organization become aware during the year of a significant diversion of the organization''s assets?', 'YESNO', 'carried', '', ''),
  ('P6_6', 'VI', 1630, '6', 'Did the organization have members or stockholders?', 'YESNO', 'carried', '', ''),
  ('P6_7A', 'VI', 1640, '7a', 'Did the organization have members, stockholders or other persons who had the power to elect or appoint members of the governing body?', 'YESNO', 'carried', '', ''),
  ('P6_7B', 'VI', 1650, '7b', 'Are any governance decisions of the organization reserved to persons other than the governing body?', 'YESNO', 'carried', '', ''),
  ('P6_8A', 'VI', 1660, '8a', 'Did the organization contemporaneously document the meetings held or written actions undertaken by the governing body?', 'YESNO', 'carried', '', ''),
  ('P6_8B', 'VI', 1670, '8b', 'Did the organization contemporaneously document the meetings of each committee with authority to act on behalf of the governing body?', 'YESNO', 'carried', '', ''),
  ('P6_9', 'VI', 1680, '9', 'Is there any officer, director, trustee or key employee listed in Part VII, Section A, who cannot be reached at the organization''s mailing address?', 'YESNO', 'carried', '', ''),
  ('P6_10A', 'VI', 1690, '10a', 'Did the organization have local chapters, branches or affiliates?', 'YESNO', 'carried', '', ''),
  ('P6_10B', 'VI', 1700, '10b', 'If Yes, did the organization have written policies governing the activities of such chapters?', 'YESNO', 'carried', '', ''),
  ('P6_11A', 'VI', 1710, '11a', 'Has the organization provided a complete copy of this Form 990 to all members of its governing body before filing the form?', 'YESNO', 'carried', '', ''),
  ('P6_12A', 'VI', 1720, '12a', 'Did the organization have a written conflict of interest policy?', 'YESNO', 'carried', '', ''),
  ('P6_12B', 'VI', 1730, '12b', 'Were officers, directors, trustees and key employees required to disclose annually interests that could give rise to conflicts?', 'YESNO', 'carried', '', ''),
  ('P6_12C', 'VI', 1740, '12c', 'Did the organization regularly and consistently monitor and enforce compliance with the policy?', 'YESNO', 'carried', '', ''),
  ('P6_13', 'VI', 1750, '13', 'Did the organization have a written whistleblower policy?', 'YESNO', 'carried', '', ''),
  ('P6_14', 'VI', 1760, '14', 'Did the organization have a written document retention and destruction policy?', 'YESNO', 'carried', '', ''),
  ('P6_15A', 'VI', 1770, '15a', 'Did the process for determining compensation of the CEO include a review and approval by independent persons, comparability data and contemporaneous substantiation?', 'YESNO', 'carried', '', ''),
  ('P6_15B', 'VI', 1780, '15b', 'Did that process apply to other officers or key employees of the organization?', 'YESNO', 'carried', '', ''),
  ('P6_16A', 'VI', 1790, '16a', 'Did the organization invest in, contribute assets to or participate in a joint venture with a taxable entity during the year?', 'YESNO', 'carried', '', ''),
  ('P6_16B', 'VI', 1800, '16b', 'If Yes, did the organization follow a written policy requiring evaluation of its participation in joint venture arrangements?', 'YESNO', 'carried', '', ''),
  ('P6_17', 'VI', 1810, '17', 'List the states with which a copy of this Form 990 is required to be filed', 'TEXT', 'carried', '', ''),
  ('P6_18', 'VI', 1820, '18', 'Indicate how the organization made its Forms 1023, 990 and 990-T available for public inspection', 'TEXT', 'carried', '', ''),
  ('P6_20', 'VI', 1830, '20', 'State the name, address and telephone number of the person who possesses the organization''s books and records', 'TEXT', 'carried', '', ''),
  ('P7_TABLE', 'VII', 1840, '1a', 'Officers, directors, trustees, key employees and highest compensated employees', 'TEXT', 'record', 'fn:officers', 'The roster carries forward from 2024 on the organisation''s own instruction; the compensation is read from the 2025 payroll register, because a carried roster is not a carried salary.'),
  ('P7_1B', 'VII', 1850, '1b', 'Sub-total of reportable compensation', 'MONEY', 'record', 'fn:officer_pay', ''),
  ('P7_1C', 'VII', 1860, '1c', 'Total from continuation sheets to Part VII, Section A', 'MONEY', 'carried', '', ''),
  ('P7_2', 'VII', 1870, '2', 'Total number of individuals who received more than $100,000 of reportable compensation from the organization', 'COUNT', 'record', 'fn:over_100k', 'The 2024 return answered 3. On the 2025 payroll register it is 4 — the roster carried forward and the register did not, which is the question v_form_990_officer_check was written to ask.'),
  ('P7_B1', 'VII', 1880, 'B 1', 'Independent contractors who received more than $100,000 of compensation', 'TEXT', 'record', 'fn:contractors', 'Every payee the ledger paid more than the threshold the form names — which is not the same list. The form wants compensation for *services*, and a payee alone cannot separate a consultant from an insurer or a utility: the seven below include Medical Mutual of Ohio and Ohio Edison. Naming the gap precisely is more use than a plausible list, and the preparer strikes the ones that are not services.'),
  ('P7_B2', 'VII', 1890, 'B 2', 'Total number of independent contractors who received more than $100,000 of compensation', 'COUNT', 'record', 'fn:contractor_count', ''),
  ('SA_STATUS', 'SCH_A', 1900, 'I 7', 'Reason for public charity status', 'CHECKBOX', 'carried', '', 'An organization that normally receives a substantial part of its support from a governmental unit or from the general public — section 170(b)(1)(A)(vi). Part II is the schedule that follows from it.'),
  ('SA_1', 'SCH_A', 1910, 'II 1', 'Gifts, grants, contributions and membership fees received', 'MONEY', 'field', 'viii:V1', 'The current-year column. The four before it are the prior return''s own, rolled one year on.'),
  ('SA_8', 'SCH_A', 1920, 'II 8', 'Gross income from interest, dividends, rents, royalties and income from similar sources', 'MONEY', 'field', 'add:viii:V3,viii:V6,viii:V5', ''),
  ('SA_9', 'SCH_A', 1930, 'II 9', 'Net income from unrelated business activities', 'MONEY', 'field', 'sub:viii:V8,ix:8b:total', 'The 2024 return put the fundraising event''s net here — 227,890, which is Schedule G Part II line 11 to the dollar. Carried as that definition rather than as the figure.'),
  ('SA_10', 'SCH_A', 1940, 'II 10', 'Other income', 'MONEY', 'field', 'viii:V11', ''),
  ('SA_5', 'SCH_A', 1950, 'II 5', 'The portion of total contributions by each person that exceeds 2% of the amount shown on line 11, column (f)', 'MONEY', 'ask', 'contributions by contributor, which this record does not hold', 'The 2024 return reported 1,491,750. It cannot be derived from a ledger that records grant income by programme rather than by donor.'),
  ('SA_PRIOR', 'SCH_A', 1960, 'II', 'The four prior columns of the support schedule', 'TEXT', 'carried', '', '2021 to 2024 as the 2024 return printed them; 2020 drops off.'),
  ('SA_14', 'SCH_A', 1970, 'II 14', 'Public support percentage for the year', 'PERCENT', 'ask', 'Schedule A Part II line 5, before a percentage can be taken', 'Line 6 is line 4 less line 5, and line 5 is the 2% excess-contributor adjustment nobody can derive from this ledger. Printing a percentage with line 5 assumed at nought would put the organisation''s public charity status on a figure nobody computed.'),
  ('SA_15', 'SCH_A', 1980, 'II 15', 'Public support percentage from the prior year''s Schedule A', 'PERCENT', 'carried', '', ''),
  ('SD_VI', 'SCH_D', 1990, 'VI', 'Land, buildings and equipment', 'MONEY', 'record', 'fn:schedule_d_vi', 'Cost and accumulated depreciation by class, which is Part X line 10 opened up. It reads bs_account, so it cannot disagree with the balance sheet above it.'),
  ('SD_XI', 'SCH_D', 2000, 'XI', 'Reconciliation of revenue per audited financial statements with revenue per return', 'MONEY', 'ask', 'the audited financial statements for 2025, which are not yet issued', ''),
  ('SD_XII', 'SCH_D', 2010, 'XII', 'Reconciliation of expenses per audited financial statements with expenses per return', 'MONEY', 'ask', 'the audited financial statements for 2025, which are not yet issued', ''),
  ('SF_1', 'SCH_F', 2020, 'I', 'Activities per region outside the United States', 'TEXT', 'carried', '', 'Part IV line 14b was answered Yes in 2024 and the schedule carries no region, no expenditure and no grantee. Carried as printed; the preparer settles whether the Yes or the empty schedule is the right one.'),
  ('SG_EVENT', 'SCH_G', 2030, 'II', 'Fundraising event', 'TEXT', 'carried', '', ''),
  ('SG_1', 'SCH_G', 2040, 'II 1', 'Gross receipts', 'MONEY', 'field', 'viii:V8', '2024 reported 367,629 against 2025''s much smaller figure. The two years answer differently whether an event sponsorship is a contribution on line 1 or event income on line 8a, and the difference is on the face of this schedule rather than netted into it.'),
  ('SG_3', 'SCH_G', 2050, 'II 3', 'Gross income (line 1 minus line 2)', 'MONEY', 'field', 'viii:V8', ''),
  ('SG_10', 'SCH_G', 2060, 'II 10', 'Direct expense summary', 'MONEY', 'field', 'ix:8b:total', ''),
  ('SG_11', 'SCH_G', 2070, 'II 11', 'Net income summary', 'MONEY', 'field', 'sub:viii:V8,ix:8b:total', ''),
  ('SG_SPLIT', 'SCH_G', 2080, 'II 4-9', 'Direct expenses by kind — cash prizes, non-cash prizes, rent and facility costs, food and beverages, entertainment, other', 'TEXT', 'ask', 'the event''s direct expenses split by the six kinds the schedule prints', 'The ledger carries the expenses and not the split; the 2024 return reported 50,000 / 14,130 / 39,557 / 7,584 / 28,468.'),
  ('SI_1', 'SCH_I', 2090, 'I 1', 'Does the organization maintain records to substantiate the amount of the grants, the grantees'' eligibility and the selection criteria?', 'YESNO', 'carried', '', ''),
  ('SI_TABLE', 'SCH_I', 2100, 'II', 'Grants and other assistance to domestic organizations and domestic governments', 'TEXT', 'record', 'fn:schedule_i', 'Every payee on Part IX line 1 above the $5,000 the schedule names, read from the ledger. The EIN and IRC section of each grantee are not on this record and print as asked rather than blank.'),
  ('SI_3', 'SCH_I', 2110, 'II 3', 'Enter total number of other organizations listed', 'COUNT', 'record', 'fn:schedule_i_count', ''),
  ('SJ', 'SCH_J', 2120, '', 'Compensation information for certain officers, directors, trustees, key employees and highest compensated employees', 'TEXT', 'record', 'fn:schedule_j', 'Follows Part VII: the people the roster names, with the compensation the register carries.'),
  ('SO', 'SCH_O', 2130, '', 'Supplemental information to Form 990', 'TEXT', 'carried', '', 'Every narrative the 2024 return gave, plus the explanations this return owes for its own asked fields. Schedule O is where a return says what it could not answer, which is the whole of this document''s discipline.');
