-- 112 — the whole return, field by field, and where each 2025 answer comes from
--
-- `094`–`097` put Parts VIII and IX on the return's own lines and `110`–`111`
-- did Part X. Those are the three financial statements and they are **a third
-- of the document**: the 2024 filing is thirty-six pages, and the rest of it
-- is a mission statement, four checklists of Yes and No, a governance section,
-- a signature block and seven schedules. A "2025 Form 990" that prints three
-- statements and nothing else is not a return; it is three schedules with a
-- cover.
--
-- So this is the other two thirds, transcribed from the filed 2024 return —
-- **every field, with its 2024 answer as printed** — and beside each one,
-- where the 2025 answer comes from. That last column is the whole design,
-- because there are only four honest answers and they lead to different work:
--
--   `record`   the record answers it, and `source` says which view. Nothing
--              is recalled and nothing is computed twice.
--   `field`    the form defines it as another line of itself — *must equal
--              Part VIII, column (A), line 12*. A reference, not a
--              derivation.
--   `carried`  a fact about the organisation that 2025 does not move: the
--              EIN, the state of domicile, whether there is a written
--              conflict of interest policy. **Carried is not measured**, and
--              the rendered return says so on every one, because a carried
--              answer somebody has to confirm and a read one they do not are
--              different facts and printing them alike is how a return gets
--              signed over a stale answer.
--   `ask`      nobody has answered it for 2025 and nothing on the record can.
--              It prints as the question rather than blank and rather than
--              the 2024 answer — *a blank is unanswered, and unanswered is a
--              value*, which this file has held since the intake was built.
--
-- The 2024 column is a **source document**, the way `form_990_prior_year`
-- already is for Parts VIII and IX: read off the filing that has been in
-- `docs/source-documents/tax-filings/` since the foundation was loaded, not
-- recalled. *Figures in a document for somebody else get read from the
-- record, not recalled* — applied to somebody else's document.

CREATE TABLE form_990_field (
  field_id   text PRIMARY KEY,
  part       text NOT NULL,
  seq        integer NOT NULL,
  line_no    text NOT NULL DEFAULT '',
  label      text NOT NULL,
  kind       text NOT NULL
             CHECK (kind IN ('MONEY','COUNT','PERCENT','YESNO','TEXT',
                             'CHECKBOX','HEADING')),
  answer     text NOT NULL
             CHECK (answer IN ('record','field','carried','ask')),
  source     text NOT NULL DEFAULT '',
  note       text NOT NULL DEFAULT '',
  -- A field answered from the record or by reference has to say from what.
  -- A source with nothing in it is the citation-with-no-document shape, and
  -- this register is large enough that one would never be noticed by eye.
  CONSTRAINT a_read_field_names_its_source
    CHECK (answer NOT IN ('record','field') OR length(btrim(source)) > 0),
  -- And an ask has to say what is being asked for, or it is "cannot be
  -- answered" with no way to act on it — the dead end this file keeps finding.
  CONSTRAINT an_ask_says_what_it_wants
    CHECK (answer <> 'ask' OR length(btrim(source)) >= 12)
);

COMMENT ON TABLE form_990_field IS
  'Every field of Form 990 outside Parts VIII, IX and X, and where the '
  'answer comes from. Four answers — read, referenced, carried, asked — '
  'because a carried answer and a measured one are different facts and a '
  'return that prints them alike gets signed over a stale one.';

CREATE TABLE form_990_prior_field (
  period    text NOT NULL REFERENCES fiscal_period(period),
  field_id  text NOT NULL REFERENCES form_990_field(field_id),
  value     text NOT NULL,
  PRIMARY KEY (period, field_id)
);

COMMENT ON TABLE form_990_prior_field IS
  'The filed return, as printed. A source document transcribed, not a '
  'constant in a script — the rule form_990_prior_year already follows for '
  'Parts VIII and IX.';


-- The 2024 filing, as printed. Fields the return left blank carry no
-- row: a blank is unanswered, and unanswered is a value.
